def transform(grid):
    # Find the uniform separator row or column and extract the lower/right panel.
    h, w = len(grid), len(grid[0])
    row_sep = next((r for r, row in enumerate(grid) if len(set(row)) == 1), None)
    if row_sep is not None:
        panel = grid[row_sep + 1:]
    else:
        col_sep = next(c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1)
        panel = [row[col_sep + 1:] for row in grid]
    colors = {x for row in panel for x in row}
    fg = min(colors, key=lambda v: sum(x == v for row in panel for x in row))
    return [[3 if x == fg else x for x in row] for row in panel]

