def transform(grid):
    h,w=len(grid),len(grid[0])
    r=next((i for i,row in enumerate(grid) if len(set(row))==1),None)
    if r is not None:
        a,b=grid[:r],grid[r+1:]
    else:
        c=next(j for j in range(w) if len({grid[i][j] for i in range(h)})==1)
        a=[row[:c] for row in grid]; b=[row[c+1:] for row in grid]
    def fg(panel):
        counts={}
        for row in panel:
            for x in row: counts[x]=counts.get(x,0)+1
        bg=max(counts,key=counts.get)
        return bg,next(x for x in counts if x!=bg)
    ba,fa=fg(a); bb,fb=fg(b)
    return [[3 if x==fa and y==fb else ba for x,y in zip(rx,ry)] for rx,ry in zip(a,b)]

